53	class _ExpiryOverlayHostState extends State<ExpiryOverlayHost> {
54	  StreamSubscription<SessionStatus>? _subscription;
55	
56	  // Same two one-shot guards `main.dart` used to own (code review of
57	  // story-1-5): `_expiryOverlayShown` is a per-episode latch (nothing
58	  // today transitions `SessionStatus` back out of `expired`, so without
59	  // it a later event on this same subscription would reopen the overlay
60	  // on top of wherever the user already navigated after confirming it);
61	  // `_reauthRouteRequested` guards the dialog's own confirm callback
62	  // against a rapid double-tap during its 180ms exit fade.
63	  bool _expiryOverlayShown = false;
64	  bool _reauthRouteRequested = false;
65	
66	  @override
67	  void initState() {
68	    super.initState();
69	    _subscription = widget.sessionRepository.statusStream.listen(
70	      _onStatus,
71	      // Mirrors `SessionRepositoryImpl`'s own internal subscriptions — no
72	      // current implementation ever errors on this stream, but a future
73	      // one that did must not surface as an unhandled zone exception.
74	      onError: (_, _) {},
75	    );
76	  }
77	
78	  @override
79	  void dispose() {
80	    unawaited(_subscription?.cancel());
81	    super.dispose();
82	  }
83	
84	  void _onStatus(SessionStatus status) {
85	    if (status != SessionStatus.expired || _expiryOverlayShown) {
86	      return;
87	    }
88	    _expiryOverlayShown = true;
89	    // `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a
90	    // route, which must never happen mid-build/mid-stream-callback —
91	    // deferred to `addPostFrameCallback`, same as `main.dart` did.
92	    WidgetsBinding.instance.addPostFrameCallback((_) {
93	      if (!mounted) {
94	        return;
95	      }
96	      // This widget's own `context` sits *above* the router's `Navigator`
97	      // (see class doc) — `showGeneralDialog` needs a context *below* it,
98	      // which `NavigatorState.overlay`'s own context always is.
99	      final overlayContext = widget.navigatorKey.currentState?.overlay?.context;
100	      if (overlayContext == null) {
101	        // Navigator not mounted yet — nothing to show an overlay over.
102	        _expiryOverlayShown = false;
103	        return;
104	      }
105	      unawaited(
106	        ConfirmationDialog.show(
107	          context: overlayContext,
108	          builder: (dialogContext) => ConfirmationDialog(
109	            icon: Icons.lock_outline,
110	            title: 'Sessão expirada',
111	            message:
112	                'Sua sessão expirou por segurança. Entre novamente para '
113	                'continuar — sua conversa continua aqui.',
114	            caption: 'o histórico e a posição do scroll são preservados',
115	            confirmLabel: 'Entrar novamente',
116	            barrierColor: DesignTokens.colorScrim,
117	            onConfirm: () {
118	              if (_reauthRouteRequested) {
119	                return;
120	              }
121	              _reauthRouteRequested = true;
122	              if (dialogContext.mounted) {
123	                Navigator.of(dialogContext).pop();
124	              }
125	              widget.router.go(AppRoutePaths.reauth);
126	            },
127	          ),
128	        ),
129	      );
130	    });
131	  }
132	
133	  @override
134	  Widget build(BuildContext context) => widget.child;
135	}
