3	/// AD-4/AD-5 — the one place a `DioException` is mapped to the backend's
4	/// error `code` (`error-taxonomy.md`), shared by `ApiClient` (which turns it
5	/// into a `Failure`) and `RetryInterceptor` (which decides whether to
6	/// retry). Previously reimplemented independently in both files, which let
7	/// a client-side timeout and a cancelled request both be misread as
8	/// `NETWORK_OFFLINE`.
9	///
10	/// Returns `null` when no code can be determined: a cancelled request
11	/// (`DioExceptionType.cancel`) or an HTTP response that doesn't carry the
12	/// expected `{code, message, retryable}` body. Neither is retryable, and
13	/// both end up mapped to `Failure.malformedResponse` by the caller.
14	String? dioErrorCodeOf(DioException e) {
15	  final data = e.response?.data;
16	  if (data is Map && data['code'] is String) {
17	    return data['code'] as String;
18	  }
19	  switch (e.type) {
20	    case DioExceptionType.connectionTimeout:
21	    case DioExceptionType.sendTimeout:
22	    case DioExceptionType.receiveTimeout:
23	      return 'NETWORK_TIMEOUT';
24	    case DioExceptionType.cancel:
25	      return null;
26	    default:
27	      break;
28	  }
29	  if (e.response == null) {
30	    return 'NETWORK_OFFLINE';
31	  }
32	  return null;
33	}
